-- Editable simulation preset derived from the publicly documented 2026 weekday schedule.
create unique index if not exists schedule_template_preset_identity on public.schedule_templates(preset_name,callsign_template,scheduled_departure_local,origin_airport_id,destination_airport_id);
create table if not exists public.schedule_automation_state(id boolean primary key default true check(id),enabled boolean not null default true,horizon_days int not null default 14,last_run_at timestamptz,last_created int default 0,last_skipped int default 0,last_error text,updated_at timestamptz default now());
alter table public.schedule_automation_state enable row level security;
create policy schedule_automation_ops_read on public.schedule_automation_state for select to authenticated using(public.has_any_role(auth.uid(),array['dispatcher','operations_manager','owner','system_administrator']::public.app_role[]));
insert into public.schedule_automation_state(id) values(true) on conflict(id) do nothing;

