insert into public.schedule_templates(name,callsign_template,flight_number,origin_airport_id,destination_airport_id,scheduled_departure_local,scheduled_arrival_local,days_of_week,aircraft_category,preferred_aircraft_type_id,altitude_ft,operation_type,variability_minutes,operation_probability,active,source_reference,admin_notes,preset_name,generation_reason)
select p.name,p.callsign,replace(p.callsign,'JANET','JAN'),o.id,d.id,p.dep,p.arr,p.days,'commuter',t.id,p.altitude,'commuter',p.variance,p.probability,true,'https://www.dreamlandresort.com/info/janet_schedule.html',p.notes,'Publicly Documented JANET-Inspired Weekday Schedule – 2026 Reference','Public reference schedule preset; fictional simulation instance' from preset p join public.airports o on o.local_code=p.origin_code join public.airports d on d.local_code=p.dest_code join public.aircraft_types t on t.code='B737'
on conflict(preset_name,callsign_template,scheduled_departure_local,origin_airport_id,destination_airport_id) do update set scheduled_arrival_local=excluded.scheduled_arrival_local,days_of_week=excluded.days_of_week,altitude_ft=excluded.altitude_ft,variability_minutes=excluded.variability_minutes,operation_probability=excluded.operation_probability,active=true,source_reference=excluded.source_reference,admin_notes=excluded.admin_notes;

create or replace function public.run_schedule_automation() returns jsonb language plpgsql security definer set search_path='' as $$
declare s public.schedule_automation_state%rowtype;r record;
begin select * into s from public.schedule_automation_state where id=true for update;if not s.enabled then return jsonb_build_object('enabled',false);end if;
begin select * into r from public.generate_scheduled_flights(current_date,s.horizon_days);update public.schedule_automation_state set last_run_at=now(),last_created=r.created_count,last_skipped=r.skipped_count,last_error=null,updated_at=now() where id=true;return jsonb_build_object('enabled',true,'created',r.created_count,'skipped',r.skipped_count);
exception when others then update public.schedule_automation_state set last_run_at=now(),last_error=sqlerrm,updated_at=now() where id=true;raise;end;end$$;
grant execute on function public.run_schedule_automation() to authenticated,service_role;
do $$begin create extension if not exists pg_cron with schema pg_catalog;exception when others then raise notice 'pg_cron unavailable; use Supabase Cron to call public.run_schedule_automation hourly';end$$;
do $$begin if exists(select 1 from pg_extension where extname='pg_cron') then begin perform cron.unschedule('jva-automatic-schedule');exception when others then null;end;perform cron.schedule('jva-automatic-schedule','17 * * * *','select public.run_schedule_automation()');end if;end$$;
select public.run_schedule_automation();
notify pgrst,'reload schema';
